package com._8x8.herd.device_logs.upload.trust;

import com._8x8.herd.device_logs.contract.MacAddress;
import com._8x8.herd.device_logs.upload.config.DeviceLogsProperties;

import java.io.ByteArrayInputStream;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.security.cert.CertificateException;
import java.security.cert.CertificateFactory;
import java.security.cert.X509Certificate;
import java.util.List;
import java.util.Locale;
import java.util.stream.Stream;

import javax.naming.InvalidNameException;
import javax.naming.ldap.LdapName;
import javax.security.auth.x500.X500Principal;

import org.springframework.http.HttpHeaders;
import org.springframework.stereotype.Component;

/**
 * Turns the headers the ALB adds after the mTLS handshake into a {@link ClientIdentity}. The only class that reads
 * them, and it reads them defensively (ADR 0004), so it stays safe whether or not the ALB overwrites copies a client
 * sent itself.
 */
@Component
public class AlbHeaderTrust {

    private final DeviceLogsProperties.Trust names;

    public AlbHeaderTrust(DeviceLogsProperties properties) {
        this.names = properties.trust();
    }

    /**
     * @throws UntrustedIdentityException if a certificate header is missing or repeated, the leaf does not parse, its
     *                                    CN is not 12 uppercase hex digits or differs from the Subject header, or
     *                                    X-Forwarded-For has no last entry
     */
    public ClientIdentity identify(HttpHeaders headers) {
        String subject = exactlyOnce(headers, names.subject());
        exactlyOnce(headers, names.issuer());
        exactlyOnce(headers, names.validity());
        exactlyOnce(headers, names.serialNumber());
        X509Certificate leaf = parseLeaf(exactlyOnce(headers, names.leaf()));

        String leafCn = commonName(leaf.getSubjectX500Principal().getName(X500Principal.RFC2253), "leaf certificate");
        // Check: the CN is 12 hex digits, all uppercase, as the phone certificates are issued.
        MacAddress mac = MacAddress.parse(leafCn)
                .filter(parsed -> parsed.uppercase().equals(leafCn))
                .orElseThrow(() -> new UntrustedIdentityException("leaf certificate CN is not 12 uppercase hex digits"));
        // Check: the Subject header and the leaf are two copies of the same name, so their CNs must agree.
        if (!leafCn.equals(commonName(subject, "Subject header"))) {
            throw new UntrustedIdentityException("leaf certificate CN differs from the Subject header CN");
        }
        return new ClientIdentity(mac, serial(leaf), lastForwardedFor(headers));
    }

    // HttpHeaders keeps one entry per header line and does not split on commas, which matters because a Subject
    // holds commas.
    private static String exactlyOnce(HttpHeaders headers, String name) {
        List<String> values = headers.getOrEmpty(name);
        // Check: zero copies or two copies both fail, because we can't tell which copy the ALB wrote.
        if (values.size() != 1) {
            throw new UntrustedIdentityException(name + " appears " + values.size() + " times, expected once");
        }
        return values.get(0);
    }

    // The ALB leaves + unescaped, and URLDecoder would turn it into a space and break the base64. Escaping it first
    // also copes with an ALB that does encode it.
    private static X509Certificate parseLeaf(String urlEncodedPem) {
        try {
            // Check: the decoded text must be an X.509 certificate. The ALB already checked trust and expiry during the
            // handshake, so this only turns the text back into a certificate.
            String pem = URLDecoder.decode(urlEncodedPem.replace("+", "%2B"), StandardCharsets.UTF_8);
            return (X509Certificate) CertificateFactory.getInstance("X.509")
                    .generateCertificate(new ByteArrayInputStream(pem.getBytes(StandardCharsets.US_ASCII)));
        } catch (IllegalArgumentException | CertificateException ignored) {
            // No cause: URLDecoder's message quotes the bad escape, which comes from the client.
            throw new UntrustedIdentityException("leaf certificate is not a URL-encoded PEM");
        }
    }

    private static String commonName(String rfc2253, String source) {
        try {
            List<String> cns = new LdapName(rfc2253).getRdns().stream()
                    .filter(rdn -> rdn.getType().equalsIgnoreCase("CN"))
                    .map(rdn -> rdn.getValue().toString())
                    .toList();
            // Check: exactly one CN, because the CN is the MAC and two would leave us guessing.
            if (cns.size() != 1) {
                throw new UntrustedIdentityException(source + " has " + cns.size() + " CNs, expected one");
            }
            return cns.get(0);
        } catch (InvalidNameException ignored) {
            // No cause: its message repeats the whole name, which comes from the client.
            throw new UntrustedIdentityException(source + " is not an RFC 2253 name");
        }
    }

    // Whole bytes, as the ALB writes the Serial-Number header (03A5B1, not 3A5B1).
    private static String serial(X509Certificate leaf) {
        String hex = leaf.getSerialNumber().toString(16).toUpperCase(Locale.ROOT);
        return hex.length() % 2 == 0 ? hex : "0" + hex;
    }

    // The ALB appends the address it saw to the end, so earlier entries are whatever the client sent.
    private String lastForwardedFor(HttpHeaders headers) {
        List<String> entries = headers.getOrEmpty(names.forwardedFor()).stream()
                .flatMap(line -> Stream.of(line.split(",", -1)))
                .map(String::trim)
                .toList();
        // Check: a missing header, an empty value or a trailing comma leaves no last entry to use.
        if (entries.isEmpty() || entries.get(entries.size() - 1).isEmpty()) {
            throw new UntrustedIdentityException(names.forwardedFor() + " has no last entry");
        }
        return entries.get(entries.size() - 1);
    }
}

